#!/usr/bin/env python3
import sys
import numpy as np
sys.setrecursionlimit(10 ** 7)


def solve(N: int, A: "List[int]"):
    if N == 1:
        print(0)
    else:
        m1 = max(A)
        max_idx = np.where(np.array(A) == max(A))
        if len(max_idx[0]) > 1:
            for i in range(N):
                print(m1)
        else:
            m2 = sorted(set(A))[-2]
            max_idx = np.argmax(np.array(A))
            for i in range(N):
                if i == max_idx:
                    print(m2)
                else:
                    print(m1)
    return


# Generated by 1.1.5 https://github.com/kyuridenamida/atcoder-tools
# (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    A = [int(next(tokens)) for _ in range(N)]  # type: "List[int]"
    solve(N, A)


if __name__ == '__main__':
    main()
